// PV2 acceptance for uploads, dedup, versions, trash and quotas, over the real router, the real index core on
// SQLite, the real policy engine and an in-memory R2. Fixtures are generated bytes, never real files.

import { randomBytes } from "node:crypto";
import { UPLOAD_PART_SIZE } from "@saas/contracts/media";
import { FakeDigestStream, World, sha256hex, type User } from "./harness.js";

// Production verifies multipart commits through workerd's crypto.DigestStream; these tests do too.
beforeAll(() => {
  (globalThis as unknown as { crypto: { DigestStream?: unknown } }).crypto.DigestStream = FakeDigestStream;
});


describe("uploads, dedup, versions, trash and quotas", () => {
  let w: World;
  let A: { id: string; pub: string };
  let B: { id: string; pub: string };
  let owner: User, editor: User, viewer: User, ownerB: User, guest: User;
  let lib: { id: string };
  let base: string;

  beforeEach(async () => {
    w = new World();
    A = w.newOrg();
    B = w.newOrg();
    owner = w.newUser("owner");
    editor = w.newUser("editor");
    viewer = w.newUser("viewer");
    ownerB = w.newUser("owner-b");
    guest = w.newUser("guest");
    w.grant(A, owner, "owner");
    w.grant(A, editor, "builder");
    w.grant(A, viewer, "viewer");
    w.grant(B, ownerB, "owner");
    lib = (await w.call(owner, "POST", `/v1/organizations/${A.pub}/libraries`, { name: "Shots" })).json.data.library;
    base = `/v1/organizations/${A.pub}/libraries/${lib.id}`;
    await w.call(owner, "PUT", `${base}/members/${editor.id}`, { role: "editor" });
    await w.call(owner, "PUT", `${base}/members/${viewer.id}`, { role: "viewer" });
    await w.call(owner, "POST", `${base}/invitations`, { email: guest.email, role: "uploader" });
    await w.call(guest, "POST", "/v1/media/invitations/accept");
  });

  async function upload(user: User, name: string, bytes: Uint8Array, extra: Record<string, unknown> = {}) {
    const created = await w.call(user, "POST", `${base}/uploads`, { name, size: bytes.length, sha256: sha256hex(bytes), mime: "image/png", ...extra });
    if (created.status !== 201) return { created, commit: null as null | { status: number; json: any } };
    const s = created.json.data.session;
    for (let n = 1; n <= s.partCount; n++) {
      const part = bytes.subarray((n - 1) * s.partSize, Math.min(n * s.partSize, bytes.length));
      const r = await w.put(user, `${base}/uploads/${s.id}/parts/${n}`, part);
      expect([n, r.status]).toEqual([n, 200]);
    }
    const commit = await w.call(user, "POST", `${base}/uploads/${s.id}/commit`);
    return { created, commit };
  }

  const usage = async () => (await w.call(owner, "GET", `/v1/organizations/${A.pub}/media-usage`)).json.data.usage;

  it("a small file uploads in one verified part and downloads byte-for-byte", async () => {
    const bytes = randomBytes(1024);
    const { created, commit } = await upload(editor, "a.png", bytes);
    expect(created.json.data.session).toMatchObject({ mode: "single", partCount: 1, path: "/a.png" });
    expect(commit!.status).toBe(200);
    const file = commit!.json.data.file;
    expect(file).toMatchObject({ name: "a.png", path: "/a.png", size: 1024, sha256: sha256hex(bytes), version: 1, status: "private", uploadedBy: editor.id });
    const got = await w.bytes(viewer, `${base}/files/${file.id}/content`);
    expect(got.status).toBe(200);
    expect(Buffer.from(got.bytes).equals(bytes)).toBe(true);
    expect(got.headers.get("cache-control")).toBe("private, no-store");
    expect(await usage()).toMatchObject({ storageBytes: 1024, uploadsThisMonth: 1 });
    // every stored key lives under this library's prefix
    for (const key of w.bucket.objects.keys()) expect(key.startsWith(`org/${A.id}/lib/`)).toBe(true);
  });

  it("a multipart upload resumes from its last part and verifies the whole file's SHA-256", async () => {
    const bytes = randomBytes(UPLOAD_PART_SIZE * 2 + 5000);
    const sha = sha256hex(bytes);
    const s = (await w.call(editor, "POST", `${base}/uploads`, { name: "big.bin", size: bytes.length, sha256: sha, mime: "application/octet-stream" })).json.data.session;
    expect(s).toMatchObject({ mode: "multipart", partCount: 3, partSize: UPLOAD_PART_SIZE, uploadedParts: [] });
    expect((await w.put(editor, `${base}/uploads/${s.id}/parts/1`, bytes.subarray(0, UPLOAD_PART_SIZE))).status).toBe(200);
    // "the browser closed": the client asks where it was, then continues
    const resumed = (await w.call(editor, "GET", `${base}/uploads/${s.id}`)).json.data.session;
    expect(resumed.uploadedParts).toEqual([1]);
    expect((await w.call(editor, "POST", `${base}/uploads/${s.id}/commit`)).json.error.details.missing).toEqual([2, 3]);
    await w.put(editor, `${base}/uploads/${s.id}/parts/2`, bytes.subarray(UPLOAD_PART_SIZE, 2 * UPLOAD_PART_SIZE));
    await w.put(editor, `${base}/uploads/${s.id}/parts/3`, bytes.subarray(2 * UPLOAD_PART_SIZE));
    const commit = await w.call(editor, "POST", `${base}/uploads/${s.id}/commit`);
    expect(commit.status).toBe(200);
    expect(commit.json.data.file).toMatchObject({ size: bytes.length, sha256: sha });
    const got = await w.bytes(editor, `${base}/files/${commit.json.data.file.id}/content`);
    expect(sha256hex(got.bytes)).toBe(sha);
  }, 60_000);

  it("bytes that don't match the declared SHA-256 never become a file", async () => {
    const bytes = randomBytes(2048);
    const wrong = sha256hex(randomBytes(16));
    const single = (await w.call(editor, "POST", `${base}/uploads`, { name: "x.png", size: 2048, sha256: wrong })).json.data.session;
    expect((await w.put(editor, `${base}/uploads/${single.id}/parts/1`, bytes)).json.error.code).toBe("hash_mismatch");

    const big = randomBytes(UPLOAD_PART_SIZE + 10);
    const multi = (await w.call(editor, "POST", `${base}/uploads`, { name: "y.bin", size: big.length, sha256: wrong })).json.data.session;
    await w.put(editor, `${base}/uploads/${multi.id}/parts/1`, big.subarray(0, UPLOAD_PART_SIZE));
    await w.put(editor, `${base}/uploads/${multi.id}/parts/2`, big.subarray(UPLOAD_PART_SIZE));
    const commit = await w.call(editor, "POST", `${base}/uploads/${multi.id}/commit`);
    expect([commit.status, commit.json.error.code]).toEqual([422, "hash_mismatch"]);
    expect(w.bucket.objects.size).toBe(0);
    expect((await w.call(editor, "GET", `${base}/files`)).json.data.files).toEqual([]);
    expect((await usage()).storageBytes).toBe(0);
  }, 60_000);

  it("the same bytes twice cost no storage; an uploader still has to send them", async () => {
    const bytes = randomBytes(4096);
    const first = await upload(editor, "one.png", bytes);
    expect(first.commit!.json.data.deduplicated).toBe(false);

    // A reader of the library may skip sending bytes it already has access to.
    const again = await w.call(editor, "POST", `${base}/uploads`, { name: "two.png", size: 4096, sha256: sha256hex(bytes) });
    expect(again.status).toBe(200);
    expect(again.json.data).toMatchObject({ deduplicated: true, file: { path: "/two.png", sha256: sha256hex(bytes) } });

    // An uploader can't read others' files, so knowing the hash isn't enough: it gets a session and sends bytes.
    const g = await upload(guest, "three.png", bytes);
    expect(g.created.status).toBe(201);
    expect(g.commit!.json.data.deduplicated).toBe(true);

    expect(w.bucket.objects.size).toBe(1);
    expect(await usage()).toMatchObject({ storageBytes: 4096, uploadsThisMonth: 3 });
    const blob = [...w.index.cores.values()][0]!.findBlob(sha256hex(bytes));
    expect(blob?.refcount).toBe(3);
  });

  it("trash and restore keep the file; purge deletes the blob only when nothing references it", async () => {
    const bytes = randomBytes(3000);
    const a = (await upload(editor, "a.png", bytes)).commit!.json.data.file;
    const b = (await w.call(editor, "POST", `${base}/uploads`, { name: "b.png", size: 3000, sha256: sha256hex(bytes) })).json.data.file;

    expect((await w.call(editor, "DELETE", `${base}/files/${a.id}`)).json.data.file.status).toBe("trashed");
    expect((await w.call(editor, "GET", `${base}/files`)).json.data.files.map((f: { id: string }) => f.id)).toEqual([b.id]);
    expect((await w.call(editor, "GET", `${base}/files?trash=1`)).json.data.files.map((f: { id: string }) => f.id)).toEqual([a.id]);
    expect((await w.bytes(editor, `${base}/files/${a.id}/content`)).status).toBe(404);

    const restored = await w.call(editor, "POST", `${base}/files/${a.id}/restore`);
    expect(restored.json.data.file).toMatchObject({ id: a.id, status: "private", sha256: sha256hex(bytes) });

    await w.call(editor, "DELETE", `${base}/files/${a.id}`);
    expect((await w.call(editor, "DELETE", `${base}/files/${a.id}?permanent=1`)).json.data).toEqual({ purged: true, releasedBytes: 0 });
    expect(w.bucket.objects.size).toBe(1); // b still references the bytes

    expect((await w.call(editor, "DELETE", `${base}/files/${b.id}?permanent=1`)).status).toBe(404); // not trashed yet
    await w.call(editor, "DELETE", `${base}/files/${b.id}`);
    expect((await w.call(editor, "DELETE", `${base}/files/${b.id}?permanent=1`)).json.data).toEqual({ purged: true, releasedBytes: 3000 });
    expect(w.bucket.objects.size).toBe(0);
    expect((await usage()).storageBytes).toBe(0);
  });

  it("replacing a file keeps versions; restoring a version makes a new current one", async () => {
    const v1 = randomBytes(1000);
    const v2 = randomBytes(2000);
    const f = (await upload(editor, "logo.png", v1)).commit!.json.data.file;
    expect((await w.call(editor, "POST", `${base}/uploads`, { name: "logo.png", size: 2000, sha256: sha256hex(v2) })).status).toBe(409);
    const r = (await upload(editor, "logo.png", v2, { replace: true })).commit!.json.data.file;
    expect(r).toMatchObject({ id: f.id, version: 2, size: 2000 });
    const versions = (await w.call(editor, "GET", `${base}/files/${f.id}/versions`)).json.data.versions;
    expect(versions.map((v: { version: number; current: boolean }) => [v.version, v.current])).toEqual([[2, true], [1, false]]);
    const back = (await w.call(editor, "POST", `${base}/files/${f.id}/versions/1/restore`)).json.data.file;
    expect(back).toMatchObject({ version: 3, size: 1000, sha256: sha256hex(v1) });
    // a viewer can't replace or restore versions
    expect((await w.call(viewer, "POST", `${base}/files/${f.id}/versions/2/restore`)).status).toBe(404);
  });

  it("a session over the org's storage or upload quota is refused with quota_exceeded", async () => {
    w.db.prepare(`INSERT INTO media_org_limits (org_id, storage_bytes_limit, uploads_per_month_limit) VALUES (?, 5000, 2)`).run(A.id);
    const tooBig = await w.call(editor, "POST", `${base}/uploads`, { name: "big.png", size: 6000, sha256: sha256hex(randomBytes(8)) });
    expect([tooBig.status, tooBig.json.error.code, tooBig.json.error.details.reason]).toEqual([412, "quota_exceeded", "storage"]);
    await upload(editor, "1.png", randomBytes(10));
    await upload(editor, "2.png", randomBytes(10));
    const third = await w.call(editor, "POST", `${base}/uploads`, { name: "3.png", size: 10, sha256: sha256hex(randomBytes(8)) });
    expect([third.status, third.json.error.details.reason]).toEqual([412, "uploads"]);
    // org B's quota is untouched by org A's usage
    const libB = (await w.call(ownerB, "POST", `/v1/organizations/${B.pub}/libraries`, { name: "Org B shots" })).json.data.library;
    const okB = await w.call(ownerB, "POST", `/v1/organizations/${B.pub}/libraries/${libB.id}/uploads`, { name: "b.png", size: 6000, sha256: sha256hex(randomBytes(8)) });
    expect(okB.status).toBe(201);
  });

  it("library upload rules apply: type and size", async () => {
    await w.call(owner, "PATCH", base, { settings: { allowedTypes: ["image/*"], maxUploadBytes: 1000 } });
    const pdf = await w.call(editor, "POST", `${base}/uploads`, { name: "a.pdf", size: 10, sha256: sha256hex(randomBytes(4)), mime: "application/pdf" });
    expect([pdf.status, pdf.json.error.code]).toEqual([415, "unsupported_type"]);
    const big = await w.call(editor, "POST", `${base}/uploads`, { name: "a.png", size: 2000, sha256: sha256hex(randomBytes(4)), mime: "image/png" });
    expect([big.status, big.json.error.code]).toEqual([413, "too_large"]);
  });

  it("validates names and folders", async () => {
    const sha = sha256hex(randomBytes(4));
    for (const bad of [{ name: "a/b.png" }, { name: "" }, { name: "x.png", folder: "/../etc" }, { name: "x.png", sha256: "ABC" }, { name: "x.png", size: -1 }]) {
      expect((await w.call(editor, "POST", `${base}/uploads`, { size: 1, sha256: sha, ...bad })).status).toBe(422);
    }
    const ok = await w.call(editor, "POST", `${base}/uploads`, { name: "x.png", folder: "photos//2026/", size: 1, sha256: sha });
    expect(ok.json.data.session.path).toBe("/photos/2026/x.png");
  });

  describe("isolation", () => {
    it("roles: viewers can't upload; uploaders see and read only their own files", async () => {
      expect((await w.call(viewer, "POST", `${base}/uploads`, { name: "v.png", size: 1, sha256: sha256hex(randomBytes(1)) })).status).toBe(404);
      const mine = (await upload(guest, "mine.png", randomBytes(100))).commit!.json.data.file;
      const theirs = (await upload(editor, "theirs.png", randomBytes(100))).commit!.json.data.file;
      expect((await w.call(guest, "GET", `${base}/files`)).json.data.files.map((f: { id: string }) => f.id)).toEqual([mine.id]);
      expect((await w.bytes(guest, `${base}/files/${mine.id}/content`)).status).toBe(200);
      expect((await w.bytes(guest, `${base}/files/${theirs.id}/content`)).status).toBe(404);
      expect((await w.call(guest, "GET", `${base}/files/${theirs.id}`)).status).toBe(404);
      expect((await w.call(guest, "DELETE", `${base}/files/${mine.id}`)).status).toBe(404); // uploaders can't delete
    });

    it("an upload session belongs to the person who opened it", async () => {
      const s = (await w.call(editor, "POST", `${base}/uploads`, { name: "s.png", size: 10, sha256: sha256hex(randomBytes(1)) })).json.data.session;
      expect((await w.put(owner, `${base}/uploads/${s.id}/parts/1`, randomBytes(10))).status).toBe(404);
      expect((await w.call(owner, "POST", `${base}/uploads/${s.id}/commit`)).status).toBe(404);
      expect((await w.call(owner, "GET", `${base}/uploads/${s.id}`)).status).toBe(404);
    });

    it("another org can't reach files or sessions, under either org's path", async () => {
      const bytes = randomBytes(500);
      const f = (await upload(editor, "secret.png", bytes)).commit!.json.data.file;
      const s = (await w.call(editor, "POST", `${base}/uploads`, { name: "open.png", size: 10, sha256: sha256hex(randomBytes(1)) })).json.data.session;
      for (const org of [A.pub, B.pub]) {
        const b2 = `/v1/organizations/${org}/libraries/${lib.id}`;
        for (const [method, path] of [
          ["GET", `${b2}/files`],
          ["GET", `${b2}/files/${f.id}`],
          ["GET", `${b2}/files/${f.id}/content`],
          ["DELETE", `${b2}/files/${f.id}`],
          ["GET", `${b2}/files/${f.id}/versions`],
          ["GET", `${b2}/uploads/${s.id}`],
          ["POST", `${b2}/uploads/${s.id}/commit`],
          ["POST", `${b2}/uploads`],
        ] as const) {
          const r = method === "POST" && path.endsWith("/uploads") ? await w.call(ownerB, method, path, { name: "z.png", size: 1, sha256: sha256hex(bytes) }) : await w.call(ownerB, method, path);
          expect([method, path, r.status]).toEqual([method, path, 404]);
        }
      }
      expect((await w.call(ownerB, "GET", `/v1/organizations/${A.pub}/media-usage`)).status).toBe(404);
    });

    it("an index refuses to serve any library but its own", () => {
      const ns = w.index;
      const stub = ns.get(ns.idFromName("org:x:lib:y"));
      return stub.call({ orgId: "x", libraryId: "y" }, { op: "listFiles", limit: 1 } as never).then(async () => {
        const r = await stub.call({ orgId: "x", libraryId: "other" }, { op: "listFiles", limit: 1 } as never);
        expect(r).toMatchObject({ ok: false, code: "scope_mismatch" });
      });
    });
  });
});
